var largestUniqueNumber = function(nums) {
    const counts = new Array(1001).fill(0);
    for (const x of nums) counts[x]++;
    for (let x = 1000; x >= 0; x--) {
        if (counts[x] === 1) return x;
    }
    return -1;
};
